    solution: "WITH stats AS (SELECT AVG(amount) AS mu FROM transactions), sd AS (SELECT SQRT(AVG((amount - stats.mu) * (amount - stats.mu))) AS sigma FROM transactions CROSS JOIN stats) SELECT t.txn_id, t.account_id, t.amount, t.txn_at, ROUND((t.amount - stats.mu) / sd.sigma, 2) AS z_score FROM transactions t CROSS JOIN stats CROSS JOIN sd WHERE (t.amount - stats.mu) / sd.sigma > 3 ORDER BY z_score DESC",
