    solution: "SELECT a.country, COUNT(DISTINCT a.account_id) AS cardholders, COUNT(*) AS txn_count, ROUND(SUM(t.amount), 2) AS total_spend, ROUND(1.0 * COUNT(*) / COUNT(DISTINCT a.account_id), 2) AS txns_per_cardholder FROM transactions t JOIN accounts a ON a.account_id = t.account_id GROUP BY a.country ORDER BY total_spend DESC, a.country ASC",
