    solution: "SELECT t.txn_id, m.name AS merchant, m.category, t.amount, t.txn_at FROM transactions t JOIN merchants m ON m.merchant_id = t.merchant_id WHERE m.risk_tier = 'high' ORDER BY t.amount DESC, t.txn_id ASC LIMIT 20",
