// Append sector challenges to the main challenges array so the existing
// Coach + Practice tab UIs find them by id without code changes.
// Idempotent: if reloaded (e.g. via HMR), de-duplicate by id.
if (Array.isArray(window.challengesData)) {
  const existingIds = new Set(window.challengesData.map((c) => c.id));
  for (const ch of window.sectorChallengesData) {
    if (!existingIds.has(ch.id)) window.challengesData.push(ch);
  }
}

